export class DashboardComponent {
  get score() {
    return this.summary.productivityScore ?? 0;
  }
  get dashOffset() {
    return this.circumference * (1 - this.score / 100);
  }
  get stats() {
    return [{
      icon: '✅',
      label: 'Tasks Completed Today',
      value: this.summary.tasksCompleted,
      color: '#10b981'
    }, {
      icon: '⏳',
      label: 'Tasks Pending',
      value: this.summary.tasksPending,
      color: '#f59e0b'
    }, {
      icon: '🕐',
      label: 'Time Spent Today (min)',
      value: this.summary.timeSpent,
      color: '#6366f1'
    }];
  }
  constructor(dash, auth, zone) {
    this.dash = dash;
    this.auth = auth;
    this.zone = zone;
    this.today = new Date();
    this.loading = true;
    this.error = '';
    this.successProbability = null;
    this.successPredicting = false;
    this.successClass = '';
    this.userType = null;
    this.userTypeClass = '';
    this.clusterPredicting = false;
    this.summary = {
      tasksCompleted: 0,
      tasksPending: 0,
      timeSpent: 0,
      productivityScore: 0
    };
    this.insights = [];
    this.recommendations = [];
    this.heatmapCells = [];
    this.noWeeklyData = false;
    this.noFocusData = false;
    this.userId = '';
    this.circumference = 2 * Math.PI * 36;
    this.insightsLoading = false;
  }
  ngOnInit() {
    const user = this.auth.getUser();
    if (!user?.id) {
      this.error = 'Not authenticated';
      this.loading = false;
      return;
    }
    this.userId = user.id;
    this.loadAll();
  }
  fetchSuccessPrediction(summary, focusTrend) {
    const totalTasks = (summary.tasksCompleted ?? 0) + (summary.tasksPending ?? 0);
    const avgFocus = focusTrend?.length ? focusTrend.reduce((s, d) => s + d.avg_focus, 0) / focusTrend.length : 3;
    const avgDistraction = focusTrend?.length ? focusTrend.reduce((s, d) => s + d.avg_distraction, 0) / focusTrend.length : 1;
    const avgDuration = focusTrend?.length ? focusTrend.reduce((s, d) => s + (d.avg_duration ?? 60), 0) / focusTrend.length : 60;
    if (totalTasks === 0) return;
    this.successPredicting = true;
    this.dash.predictSuccess({
      total_tasks: totalTasks,
      avg_focus: parseFloat(avgFocus.toFixed(2)),
      avg_distraction: parseFloat(avgDistraction.toFixed(2))
    }).subscribe({
      next: res => {
        this.successProbability = res.probability;
        this.successClass = res.probability >= 70 ? 'green' : res.probability >= 40 ? 'yellow' : 'red';
        this.successPredicting = false;
      },
      error: () => {
        this.successPredicting = false;
      }
    });
    this.clusterPredicting = true;
    this.dash.predictCluster({
      avg_duration: parseFloat(avgDuration.toFixed(2)),
      avg_focus: parseFloat(avgFocus.toFixed(2)),
      avg_distraction: parseFloat(avgDistraction.toFixed(2)),
      total_tasks: totalTasks
    }).subscribe({
      next: res => {
        this.userType = res.label;
        this.userTypeClass = res.label === 'Highly Focused' ? 'green' : res.label === 'Average Performer' ? 'yellow' : 'red';
        this.clusterPredicting = false;
      },
      error: () => {
        this.clusterPredicting = false;
      }
    });
  }
  ngOnDestroy() {
    [this.lineChart, this.pieChart, this.barChart, this.focusChart].forEach(c => c?.destroy());
  }
  loadAll() {
    this.loading = true;
    this.error = '';
    const safe = (obs, fallback) => obs.pipe(catchError(() => of(fallback)));
    forkJoin({
      summary: safe(this.dash.getSummary(this.userId), {
        tasksCompleted: 0,
        tasksPending: 0,
        timeSpent: 0,
        productivityScore: 0
      }),
      trend: safe(this.dash.getTaskTrend(this.userId), []),
      category: safe(this.dash.getCategoryDistribution(this.userId), []),
      heatmap: safe(this.dash.getHeatmap(this.userId), []),
      weekly: safe(this.dash.getWeeklyTasks(this.userId), []),
      focus: safe(this.dash.getFocusTrend(this.userId), [])
    }).subscribe({
      next: res => {
        this.summary = res.summary;
        this.buildHeatmap(res.heatmap);
        this.noWeeklyData = !res.weekly?.length;
        this.noFocusData = !res.focus?.length;
        this.loading = false;
        this.fetchSuccessPrediction(res.summary, res.focus);
        this.renderLineChart(res.trend);
        this.renderPieChart(res.category);
        this.renderBarChart(res.weekly);
        this.renderFocusChart(res.focus);
        this.loadInsights();
      },
      error: e => {
        this.error = e?.error?.detail || 'Failed to load dashboard. Is the backend running?';
        this.loading = false;
      }
    });
  }
  loadInsights() {
    this.insightsLoading = true;
    this.dash.getInsights(this.userId).subscribe({
      next: res => {
        this.insights = res.insights;
        this.recommendations = res.recommendations;
        this.insightsLoading = false;
      },
      error: () => {
        this.insightsLoading = false;
      }
    });
  }
  refresh() {
    this.dash.invalidate();
    this.dash.clearInsightsCache(this.userId).subscribe({
