      error: () => this._doRefresh() // proceed even if cache-bust fails
    });
  }
  _doRefresh() {
    [this.lineChart, this.pieChart, this.barChart, this.focusChart].forEach(c => c?.destroy());
    this.lineChart = this.pieChart = this.barChart = this.focusChart = null;
    this.insights = [];
    this.recommendations = [];
    this.loadAll();
  }
  buildHeatmap(data) {
    const map = {};
    data.forEach(d => map[d.date] = d.count);
    const maxCount = Math.max(...data.map(d => d.count), 1);
    this.heatmapCells = [];
    const today = new Date();
    for (let i = 29; i >= 0; i--) {
      const d = new Date(today);
      d.setDate(today.getDate() - i);
      const key = d.toISOString().split('T')[0];
      const label = d.toLocaleDateString('en-US', {
        month: 'short',
        day: 'numeric'
      });
      const cnt = map[key] ?? 0;
      const level = cnt === 0 ? 0 : Math.ceil(cnt / maxCount * 4);
      this.heatmapCells.push({
        level,
        date: `${label} — ${cnt} tasks`
      });
    }
  }
