import { Component, OnInit, OnDestroy, ElementRef, ViewChild, NgZone } from '@angular/core';
import { forkJoin, of } from 'rxjs';
import { catchError } from 'rxjs/operators';
import { DashboardService } from '../services/dashboard.service';
import { AuthService } from '../services/auth.service';

declare const Chart: any;

@Component({
  selector: 'app-dashboard',
  templateUrl: './dashboard.html',
  styleUrls: ['./dashboard.css']
})
export class DashboardComponent implements OnInit, OnDestroy {

  @ViewChild('lineChart',  { static: true }) lineChartRef!:  ElementRef<HTMLCanvasElement>;
  @ViewChild('pieChart',   { static: true }) pieChartRef!:   ElementRef<HTMLCanvasElement>;
  @ViewChild('barChart',   { static: true }) barChartRef!:   ElementRef<HTMLCanvasElement>;
  @ViewChild('focusChart', { static: true }) focusChartRef!: ElementRef<HTMLCanvasElement>;

  today = new Date();
  loading = true;
  error = '';

  successProbability: number | null = null;
  successPredicting = false;
  successClass: 'green' | 'yellow' | 'red' | '' = '';

  userType: string | null = null;
  userTypeClass: 'green' | 'yellow' | 'red' | '' = '';
  clusterPredicting = false;

  summary: any = { tasksCompleted: 0, tasksPending: 0, timeSpent: 0, productivityScore: 0 };
  insights: string[] = [];
  recommendations: string[] = [];
  heatmapCells: { level: number; date: string }[] = [];

  noWeeklyData  = false;
  noFocusData   = false;

  private lineChart:  any;
  private pieChart:   any;
  private barChart:   any;
  private focusChart: any;
  private userId = '';

  get score() { return this.summary.productivityScore ?? 0; }
  circumference = 2 * Math.PI * 36;
  get dashOffset() { return this.circumference * (1 - this.score / 100); }

  get stats() {
    return [
      { icon: '✅', label: 'Tasks Completed Today', value: this.summary.tasksCompleted, color: '#10b981' },
      { icon: '⏳', label: 'Tasks Pending',          value: this.summary.tasksPending,   color: '#f59e0b' },
      { icon: '🕐', label: 'Time Spent Today (min)', value: this.summary.timeSpent,      color: '#6366f1' },
    ];
  }

  constructor(private dash: DashboardService, private auth: AuthService, private zone: NgZone) {}

  ngOnInit() {
    const user = this.auth.getUser();
    if (!user?.id) { this.error = 'Not authenticated'; this.loading = false; return; }
    this.userId = user.id;
    this.loadAll();
  }

  private fetchSuccessPrediction(summary: any, focusTrend: any[]) {
    const totalTasks     = (summary.tasksCompleted ?? 0) + (summary.tasksPending ?? 0);
    const avgFocus       = focusTrend?.length
      ? focusTrend.reduce((s: number, d: any) => s + d.avg_focus, 0) / focusTrend.length
      : 3;
    const avgDistraction = focusTrend?.length
      ? focusTrend.reduce((s: number, d: any) => s + d.avg_distraction, 0) / focusTrend.length
      : 1;
    const avgDuration = focusTrend?.length
      ? focusTrend.reduce((s: number, d: any) => s + (d.avg_duration ?? 60), 0) / focusTrend.length
      : 60;

    if (totalTasks === 0) return;

    this.successPredicting = true;
    this.dash.predictSuccess({
      total_tasks:     totalTasks,
      avg_focus:       parseFloat(avgFocus.toFixed(2)),
      avg_distraction: parseFloat(avgDistraction.toFixed(2))
    }).subscribe({
      next: res => {
        this.successProbability = res.probability;
        this.successClass = res.probability >= 70 ? 'green' : res.probability >= 40 ? 'yellow' : 'red';
        this.successPredicting = false;
      },
      error: () => { this.successPredicting = false; }
    });

    this.clusterPredicting = true;
    this.dash.predictCluster({
      avg_duration:    parseFloat(avgDuration.toFixed(2)),
      avg_focus:       parseFloat(avgFocus.toFixed(2)),
      avg_distraction: parseFloat(avgDistraction.toFixed(2)),
      total_tasks:     totalTasks
    }).subscribe({
      next: res => {
        this.userType = res.label;
        this.userTypeClass =
          res.label === 'Highly Focused'    ? 'green'  :
          res.label === 'Average Performer' ? 'yellow' : 'red';
        this.clusterPredicting = false;
      },
      error: () => { this.clusterPredicting = false; }
    });
  }

  ngOnDestroy() {
    [this.lineChart, this.pieChart, this.barChart, this.focusChart]
      .forEach(c => c?.destroy());
  }

  insightsLoading = false;

  loadAll() {
    this.loading = true;
    this.error = '';

    const safe = <T>(obs: Observable<T>, fallback: T) => obs.pipe(catchError(() => of(fallback)));

    forkJoin({
      summary:  safe(this.dash.getSummary(this.userId),              { tasksCompleted: 0, tasksPending: 0, timeSpent: 0, productivityScore: 0 }),
      trend:    safe(this.dash.getTaskTrend(this.userId),            []),
      category: safe(this.dash.getCategoryDistribution(this.userId), []),
      heatmap:  safe(this.dash.getHeatmap(this.userId),              []),
      weekly:   safe(this.dash.getWeeklyTasks(this.userId),          []),
      focus:    safe(this.dash.getFocusTrend(this.userId),           [])
    }).subscribe({
      next: (res: any) => {
        this.summary  = res.summary;
        this.buildHeatmap(res.heatmap);
        this.noWeeklyData = !res.weekly?.length;
        this.noFocusData  = !res.focus?.length;
        this.loading = false;
        this.fetchSuccessPrediction(res.summary, res.focus);
        this.renderLineChart(res.trend);
        this.renderPieChart(res.category);
        this.renderBarChart(res.weekly);
        this.renderFocusChart(res.focus);
        this.loadInsights();
      },
      error: (e: any) => {
        this.error   = e?.error?.detail || 'Failed to load dashboard. Is the backend running?';
        this.loading = false;
      }
    });
  }

  private loadInsights() {
    this.insightsLoading = true;
    this.dash.getInsights(this.userId).subscribe({
      next: (res: any) => {
        this.insights        = res.insights;
        this.recommendations = res.recommendations;
        this.insightsLoading = false;
      },
      error: () => { this.insightsLoading = false; }
    });
  }

  refresh() {
    this.dash.invalidate();
    this.dash.clearInsightsCache(this.userId).subscribe({
      next: () => this._doRefresh(),
      error: () => this._doRefresh()  // proceed even if cache-bust fails
    });
  }

  private _doRefresh() {
    [this.lineChart, this.pieChart, this.barChart, this.focusChart]
      .forEach(c => c?.destroy());
    this.lineChart = this.pieChart = this.barChart = this.focusChart = null;
    this.insights = [];
    this.recommendations = [];
    this.loadAll();
  }

  private buildHeatmap(data: { date: string; count: number }[]) {
    const map: Record<string, number> = {};
    data.forEach(d => (map[d.date] = d.count));
    const maxCount = Math.max(...data.map(d => d.count), 1);
    this.heatmapCells = [];
    const today = new Date();
    for (let i = 29; i >= 0; i--) {
      const d = new Date(today);
      d.setDate(today.getDate() - i);
      const key   = d.toISOString().split('T')[0];
      const label = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      const cnt   = map[key] ?? 0;
      const level = cnt === 0 ? 0 : Math.ceil((cnt / maxCount) * 4);
      this.heatmapCells.push({ level, date: `${label} — ${cnt} tasks` });
    }
  }

  private chartDefaults() {
    return {
      responsive: true,
      maintainAspectRatio: false,
      animation: { duration: 800 },
      plugins: { legend: { display: false } },
    };
  }

  private axisStyle() {
    return {
      x: { grid: { color: '#1f1f1f' }, ticks: { color: '#6b7280', font: { size: 12 } } },
      y: { grid: { color: '#1f1f1f' }, ticks: { color: '#6b7280', font: { size: 12 }, stepSize: 1 }, beginAtZero: true }
    };
  }

  private renderLineChart(data: { date: string; count: number }[]) {
    if (!this.lineChartRef?.nativeElement) return;
    this.lineChart?.destroy();
    this.lineChart = new Chart(this.lineChartRef.nativeElement, {
      type: 'line',
      data: {
        labels: data.map(d => d.date.slice(5)),
        datasets: [{
          label: 'Tasks Created',
          data: data.map(d => d.count),
          borderColor: '#f59e0b',
          backgroundColor: 'rgba(245,158,11,0.08)',
          pointBackgroundColor: '#f59e0b',
          pointRadius: 5, pointHoverRadius: 7,
          tension: 0.4, fill: true, borderWidth: 2.5
        }]
      },
      options: { ...this.chartDefaults(), scales: this.axisStyle() }
    });
  }

  private renderPieChart(data: { category: string; count: number }[]) {
    if (!this.pieChartRef?.nativeElement) return;
    this.pieChart?.destroy();
    const colors = ['#f59e0b', '#6366f1', '#10b981', '#ec4899', '#3b82f6', '#ef4444'];
    this.pieChart = new Chart(this.pieChartRef.nativeElement, {
      type: 'doughnut',
      data: {
        labels: data.map(d => d.category),
        datasets: [{
          data: data.map(d => d.count),
          backgroundColor: colors.slice(0, data.length),
          borderColor: '#111111', borderWidth: 3, hoverOffset: 8
        }]
      },
      options: {
        ...this.chartDefaults(),
        plugins: {
          legend: {
            display: true,
            position: 'bottom',
            labels: { color: '#9ca3af', font: { size: 12 }, padding: 16, boxWidth: 12 }
          }
        },
        cutout: '65%'
      }
    });
  }

  private renderBarChart(data: { date: string; count: number }[]) {
    if (!this.barChartRef?.nativeElement) return;
    this.barChart?.destroy();
    if (!data?.length) return;
    this.barChart = new Chart(this.barChartRef.nativeElement, {
      type: 'bar',
      data: {
        labels: data.map(d => d.date),
        datasets: [{
          label: 'Tasks Completed',
          data: data.map(d => d.count),
          backgroundColor: 'rgba(245,158,11,0.75)',
          borderColor: '#f59e0b',
          borderWidth: 2,
          borderRadius: 8,
          borderSkipped: false,
          hoverBackgroundColor: '#f59e0b'
        }]
      },
      options: {
        ...this.chartDefaults(),
        scales: this.axisStyle(),
        plugins: {
          legend: { display: false },
          tooltip: {
            backgroundColor: '#1a1a1a',
            titleColor: '#f59e0b',
            bodyColor: '#9ca3af',
            borderColor: '#2a2a2a',
            borderWidth: 1
          }
        }
      }
    });
  }

  private renderFocusChart(data: { date: string; avg_focus: number; avg_distraction: number }[]) {
    if (!this.focusChartRef?.nativeElement) return;
    this.focusChart?.destroy();
    if (!data?.length) return;
    this.focusChart = new Chart(this.focusChartRef.nativeElement, {
      type: 'line',
      data: {
        labels: data.map(d => d.date),
        datasets: [
          {
            label: 'Avg Focus Score',
            data: data.map(d => d.avg_focus),
            borderColor: '#10b981',
            backgroundColor: 'rgba(16,185,129,0.08)',
            pointBackgroundColor: '#10b981',
            pointRadius: 5, pointHoverRadius: 7,
            tension: 0.4, fill: true, borderWidth: 2.5
          },
          {
            label: 'Avg Distractions',
            data: data.map(d => d.avg_distraction),
            borderColor: '#ef4444',
            backgroundColor: 'rgba(239,68,68,0.06)',
            pointBackgroundColor: '#ef4444',
            pointRadius: 5, pointHoverRadius: 7,
            tension: 0.4, fill: true, borderWidth: 2.5
          }
        ]
      },
      options: {
        ...this.chartDefaults(),
        scales: {
          x: { grid: { color: '#1f1f1f' }, ticks: { color: '#6b7280', font: { size: 12 } } },
          y: { grid: { color: '#1f1f1f' }, ticks: { color: '#6b7280', font: { size: 12 } }, beginAtZero: true, max: 5 }
        },
        plugins: {
          legend: {
            display: true,
            position: 'top',
            labels: { color: '#9ca3af', font: { size: 12 }, padding: 16, boxWidth: 12, usePointStyle: true }
          },
          tooltip: {
            backgroundColor: '#1a1a1a',
            titleColor: '#e2e8f0',
            bodyColor: '#9ca3af',
            borderColor: '#2a2a2a',
            borderWidth: 1
          }
        }
      }
    });
  }
}
<!-- Header -->
<div class="dash-header">
  <div>
    <h1 class="dash-title">AI Productivity Dashboard</h1>
    <p class="dash-sub">Here's your intelligence summary for today</p>
  </div>
  <div class="header-right">
    <div class="dash-date">{{ today | date:'EEEE, MMMM d' }}</div>
    <button class="refresh-btn" (click)="refresh()" [disabled]="loading">
      <span [class.spinning]="loading">↻</span> Refresh
    </button>
  </div>
</div>

<!-- Error Banner -->
<div class="error-banner" *ngIf="error">⚠️ {{ error }}</div>

<!-- Loading Skeletons -->
<div class="loading-row" *ngIf="loading">
  <div class="skeleton" *ngFor="let i of [1,2,3,4]"></div>
</div>

<!-- ── STATS CARDS ── -->
<div class="stats-row" [hidden]="loading">
  <div class="stat-card" *ngFor="let s of stats; let i = index" [style.--delay]="i * 0.07 + 's'">
    <div class="stat-icon" [style.background]="s.color + '18'" [style.color]="s.color">{{ s.icon }}</div>
    <div class="stat-info">
      <div class="stat-label">{{ s.label }}</div>
      <div class="stat-value" [style.color]="s.color">{{ s.value }}</div>
    </div>
  </div>

  <div class="stat-card score-card">
    <div class="score-ring-wrap">
      <svg width="88" height="88" viewBox="0 0 88 88">
        <circle cx="44" cy="44" r="36" fill="none" stroke="#1f1f1f" stroke-width="7"/>
        <circle cx="44" cy="44" r="36" fill="none"
          stroke="url(#scoreGrad)" stroke-width="7" stroke-linecap="round"
          [attr.stroke-dasharray]="circumference"
          [attr.stroke-dashoffset]="dashOffset"
          transform="rotate(-90 44 44)" class="score-arc"/>
        <defs>
          <linearGradient id="scoreGrad" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stop-color="#f59e0b"/>
            <stop offset="100%" stop-color="#fcd34d"/>
          </linearGradient>
        </defs>
        <text x="44" y="49" text-anchor="middle" class="score-text">{{ score }}%</text>
      </svg>
    </div>
    <div class="stat-info">
      <div class="stat-label">Productivity Score</div>
      <div class="score-status">{{ score >= 75 ? '🔥 On Fire' : score >= 50 ? '👍 Good' : score > 0 ? '💤 Low' : '—' }}</div>
    </div>
  </div>
</div>

<!-- ── SUCCESS PROBABILITY CARD ── -->
<div class="success-card" [hidden]="loading">

  <!-- Loading -->
  <div class="success-loading" *ngIf="successPredicting">
    <span class="success-spinner"></span>
    <span>AI is predicting your success probability…</span>
  </div>

  <!-- Result -->
  <ng-container *ngIf="!successPredicting && successProbability !== null">
    <div class="success-left">
      <div class="success-icon">&#127919;</div>
      <div>
        <div class="success-label">Daily Success Probability</div>
        <div class="success-sub">Based on today’s tasks, focus &amp; distraction data</div>
      </div>
    </div>

    <div class="success-right">
      <div class="success-bar-wrap">
        <div class="success-bar-fill"
          [class.bar-green]="successClass === 'green'"
          [class.bar-yellow]="successClass === 'yellow'"
          [class.bar-red]="successClass === 'red'"
          [style.width.%]="successProbability">
        </div>
      </div>
      <div class="success-value"
        [class.val-green]="successClass === 'green'"
        [class.val-yellow]="successClass === 'yellow'"
        [class.val-red]="successClass === 'red'">
        {{ successProbability }}%
      </div>
      <div class="success-badge"
        [class.badge-green]="successClass === 'green'"
        [class.badge-yellow]="successClass === 'yellow'"
        [class.badge-red]="successClass === 'red'"
        [title]="successClass === 'green' ? 'You are on track to complete most tasks today' : successClass === 'yellow' ? 'Moderate chance — stay focused' : 'Low chance — reduce distractions'">
        {{ successClass === 'green' ? '🟢 On Track' : successClass === 'yellow' ? '🟡 Moderate' : '🔴 At Risk' }}
      </div>
    </div>
  </ng-container>

  <!-- Fallback -->
  <div class="success-fallback" *ngIf="!successPredicting && successProbability === null">
    <span>&#9888;&#65039;</span>
    <span>No prediction available — train the model or add tasks first.</span>
  </div>

</div>

<!-- ── USER TYPE CARD (Clustering) ── -->
<div class="usertype-card" [hidden]="loading">

  <div class="usertype-loading" *ngIf="clusterPredicting">
    <span class="success-spinner"></span>
    <span>AI is analyzing your productivity type…</span>
  </div>

  <ng-container *ngIf="!clusterPredicting && userType !== null">
    <div class="usertype-left">
      <div class="usertype-icon"
        [class.icon-green]="userTypeClass === 'green'"
        [class.icon-yellow]="userTypeClass === 'yellow'"
        [class.icon-red]="userTypeClass === 'red'">&#129504;</div>
      <div>
        <div class="usertype-label">Productivity Type</div>
        <div class="usertype-sub">Based on your focus, duration &amp; task patterns</div>
      </div>
    </div>
    <div class="usertype-right">
      <div class="usertype-badge"
        [class.badge-green]="userTypeClass === 'green'"
        [class.badge-yellow]="userTypeClass === 'yellow'"
        [class.badge-red]="userTypeClass === 'red'"
        [title]="userTypeClass === 'green' ? 'You maintain high focus with minimal distractions' : userTypeClass === 'yellow' ? 'Moderate productivity — room to improve focus' : 'High distraction rate detected — try focus sessions'">
        {{ userTypeClass === 'green' ? '🟢' : userTypeClass === 'yellow' ? '🟡' : '🔴' }}
        &#129504; User Type: {{ userType }}
      </div>
      <div class="usertype-tip"
        [class.tip-green]="userTypeClass === 'green'"
        [class.tip-yellow]="userTypeClass === 'yellow'"
        [class.tip-red]="userTypeClass === 'red'">
        {{ userTypeClass === 'green' ? 'Keep it up! You are in the top productivity tier.' :
           userTypeClass === 'yellow' ? 'Reduce distractions to reach the next level.' :
           'Try the Pomodoro technique to boost focus.' }}
      </div>
    </div>
  </ng-container>

  <div class="success-fallback" *ngIf="!clusterPredicting && userType === null">
    <span>&#9888;&#65039;</span>
    <span>No cluster prediction — run train_cluster_model.py first.</span>
  </div>

</div>

<!-- ── MAIN GRID: Trend + Category + Insights ── -->
<div class="main-grid" [hidden]="loading">

  <div class="charts-col">
    <div class="card chart-card">
      <div class="card-head">
        <span class="card-title">📈 Task Creation Trend</span>
        <span class="card-badge">Last 30 Days</span>
      </div>
      <div class="chart-wrap">
        <canvas #lineChart></canvas>
      </div>
    </div>

    <div class="card chart-card">
      <div class="card-head">
        <span class="card-title">🍩 Category Distribution</span>
        <span class="card-badge">All Time</span>
      </div>
      <div class="chart-wrap pie-wrap">
        <canvas #pieChart></canvas>
      </div>
    </div>
  </div>

  <div class="insights-col">
    <div class="card insights-card">
      <div class="card-head">
        <span class="card-title">🤖 AI Insights</span>
        <span class="ai-live">● Live</span>
      </div>
      <div *ngIf="insightsLoading" class="success-loading">
        <span class="success-spinner"></span>
        <span>AI is generating insights…</span>
      </div>
      <ng-container *ngIf="!insightsLoading">
        <div class="insights-list" *ngIf="insights.length; else noInsights">
          <div class="insight-item" *ngFor="let ins of insights; let i = index" [style.--delay]="i * 0.08 + 's'">
            <div class="insight-dot" style="background:#f59e0b"></div>
            <p class="insight-text">{{ ins }}</p>
          </div>
        </div>
        <ng-template #noInsights>
          <p class="empty-msg">Complete tasks to generate insights.</p>
        </ng-template>
      </ng-container>
    </div>

    <div class="card reco-card">
      <div class="card-head">
        <span class="card-title">💡 Smart Recommendations</span>
      </div>
      <div *ngIf="insightsLoading" class="success-loading">
        <span class="success-spinner"></span>
        <span>Generating recommendations…</span>
      </div>
      <ng-container *ngIf="!insightsLoading">
        <div class="reco-list" *ngIf="recommendations.length; else noReco">
          <div class="reco-item" *ngFor="let r of recommendations">
            <span class="reco-icon">💡</span>
            <span class="reco-text">{{ r }}</span>
          </div>
        </div>
        <ng-template #noReco>
          <p class="empty-msg">No recommendations yet.</p>
        </ng-template>
      </ng-container>
    </div>
  </div>

</div>

<!-- ── SECOND CHART ROW: Weekly Bar + Focus/Distraction ── -->
<div class="chart-row" [hidden]="loading">

  <!-- Weekly Tasks Bar Chart -->
  <div class="card chart-card">
    <div class="card-head">
      <span class="card-title">📊 Weekly Task Completions</span>
      <span class="card-badge">Last 7 Days</span>
    </div>
    <!-- canvas always in DOM so static ViewChild resolves; hidden only when no data -->
    <div class="chart-wrap" [hidden]="noWeeklyData">
      <canvas #barChart></canvas>
    </div>
    <!-- <div class="no-data" [hidden]="!noWeeklyData">
      <span class="no-data-icon">📭</span>
      <p>No completed tasks in the last 7 days</p>
    </div> -->
  </div>

  <!-- Focus vs Distraction Line Chart -->
  <div class="card chart-card">
    <div class="card-head">
      <span class="card-title">🧠 Focus vs Distraction</span>
      <span class="card-badge">Last 7 Days</span>
    </div>
    <!-- canvas always in DOM so static ViewChild resolves; hidden only when no data -->
    <div class="chart-wrap" [hidden]="noFocusData">
      <canvas #focusChart></canvas>
    </div>
    <!-- <div class="no-data" [hidden]="!noFocusData">
      <span class="no-data-icon">📭</span>
      <p>No focus data available yet</p>
    </div> -->
  </div>

</div>

